import React, { useState } from "react";

const ChatBotPage = () => {
    const [message, setMessage] = useState("");  // User input
    const [chatResponse, setChatResponse] = useState("");  // Chatbot reply

    const sendMessage = async () => {
        if (!message.trim()) return;  // Ignore empty messages

        try {
            const response = await fetch("http://192.168.40.1:5000/api/chat", {  
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ message: input }), 
            
            });

            const data = await response.json();
            setChatResponse(data.reply);  // Store chatbot response
        } catch (error) {
            console.error("Error sending message:", error);
            setChatResponse("Failed to connect to chatbot.");
        }
    };
    return (
        <div>
            <h1>Chatbot</h1>
            <input
                type="text"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder="Type a message..."
            />
            <button onClick={sendMessage}>Send</button>

            <p><strong>Chatbot Response:</strong> {chatResponse}</p>
        </div>
    );
};

export default ChatBotPage;
